<?php namespace App\Repositories\MongoDB; use App\Database\MongoConnection; use MongoDB\BSON\ObjectId;
abstract class MongoRepository { public function __construct(protected MongoConnection $db){} protected function id(string $id):ObjectId{return new ObjectId($id);} protected function row(object|array $v):array{$a=is_array($v)?$v:(array)$v;$a['id']=(string)$a['_id'];unset($a['_id']);foreach($a as $k=>$x)if($x instanceof \MongoDB\BSON\UTCDateTime)$a[$k]=$x->toDateTime()->format('Y-m-d H:i:s');return $a;} protected function rows(iterable $items):array{return array_map(fn($x)=>$this->row($x),iterator_to_array($items));} }
